+// limitations under the License.
+
+package promql
+
+import (
+	"cmp"
+	"math/big"
+	"net/netip"
+	"strconv"
+	"strings"
+	"time"
+	"unicode"
+	"unicode/utf8"
+
+	"github.com/facette/natsort"
+	"github.com/grafana/regexp"
+)
+
+// Label values are compared with a multi-domain typed comparison: every value
+// is first parsed into the most specific domain it belongs to, values of
+// different domains are ordered by their domain, and values of the same domain
+// are ordered by their parsed value. Values that are equal within their domain,
+// as well as values that belong to no typed domain at all, are ordered by
+// natural sort order of the original strings. That yields a stable total order
+// even when a label mixes heterogeneous typed and untyped representations.
+type labelValueClass int
+
+const (
+	// Values with leading whitespace are never parsed as a typed value and
+	// sort before everything else.
+	classLeadingSpace labelValueClass = iota
+	classPositiveInf
+	classNumber
+	classNegativeInf
+	classDuration
+	classBytes
+	classSemVer
+	classIP
+	classCIDR
+	classTimestamp
+	// Everything that is not a typed value, including the empty string.
+	classNatural
+)
+
+// typedLabelValue is a label value parsed into the domain it belongs to. Only
+// the fields belonging to the class are populated.
+type typedLabelValue struct {
+	class labelValueClass
+
+	// number holds the value of classNumber, the number of nanoseconds of
+	// classDuration and the number of bytes of classBytes.
+	number decimal
+	semVer semVersion
+	// addr holds the address of classIP as well as the network address of
+	// classCIDR, bits holds the prefix length of classCIDR.
+	addr netip.Addr
+	bits int
+	ts   time.Time
+}
+
+// compareLabelValues compares two label values with typed comparison. It is
+// consistent with equality: it only returns 0 for identical strings.
+func compareLabelValues(a, b string) int {
+	if a == b {
+		return 0
+	}
+	return compareTypedLabelValues(parseLabelValue(a), parseLabelValue(b), a, b)
+}
+
+// compareTypedLabelValues compares two already parsed label values, falling
+// back to the natural order of the original strings a and b.
+func compareTypedLabelValues(ta, tb typedLabelValue, a, b string) int {
+	if c := cmp.Compare(ta.class, tb.class); c != 0 {
+		return c
+	}
+
+	c := 0
+	switch ta.class {
+	case classNumber, classDuration, classBytes:
+		c = ta.number.compare(tb.number)
+	case classSemVer:
+		c = ta.semVer.compare(tb.semVer)
+	case classIP:
+		// netip.Addr.Compare orders IPv4 before IPv6, treating
+		// IPv4-mapped IPv6 addresses as IPv6.
+		c = ta.addr.Compare(tb.addr)
+	case classCIDR:
+		if c = ta.addr.Compare(tb.addr); c == 0 {
+			// Less specific networks first.
+			c = cmp.Compare(ta.bits, tb.bits)
+		}
+	case classTimestamp:
+		c = ta.ts.Compare(tb.ts)
+	}
+	if c != 0 {
+		return c
+	}
+
+	// Equal typed values (and values of the untyped classes) are ordered by
+	// the natural order of their original strings.
+	return naturalCompare(a, b)
+}
+
+// parseLabelValue determines the domain a label value belongs to and parses it.
+func parseLabelValue(s string) typedLabelValue {
+	if s == "" {
+		return typedLabelValue{class: classNatural}
+	}
+	if r, _ := utf8.DecodeRuneInString(s); unicode.IsSpace(r) {
+		return typedLabelValue{class: classLeadingSpace}
+	}
+
+	if v, ok := parseNumberValue(s); ok {
+		return v
+	}
+	if d, ok := parseDurationValue(s); ok {
+		return typedLabelValue{class: classDuration, number: d}
+	}
+	if d, ok := parseBytesValue(s); ok {
+		return typedLabelValue{class: classBytes, number: d}
+	}
+	if v, ok := parseSemVersion(s); ok {
+		return typedLabelValue{class: classSemVer, semVer: v}
+	}
+	if addr, err := netip.ParseAddr(s); err == nil {
+		return typedLabelValue{class: classIP, addr: addr}
+	}
+	if prefix, err := netip.ParsePrefix(s); err == nil {
+		return typedLabelValue{class: classCIDR, addr: prefix.Addr(), bits: prefix.Bits()}
+	}
+	if ts, ok := parseTimestampValue(s); ok {
+		return typedLabelValue{class: classTimestamp, ts: ts}
+	}
+
+	return typedLabelValue{class: classNatural}
+}
+
+// number, duration and byte magnitudes are all decimal numbers with an optional
+// sign and an optional scientific exponent. A bare exponent marker without
+// digits does not make a number.
+const magnitudePattern = `(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?`
+
+var (
+	numberRE   = regexp.MustCompile(`^[+-]?` + magnitudePattern + `$`)
+	infinityRE = regexp.MustCompile(`^[+-]?(?i:inf(?:inity)?)$`)
+	// A duration is a sequence of magnitudes with a unit, e.g. "1h30m".
+	durationComponentRE = regexp.MustCompile(`^([+-]?)(` + magnitudePattern + `)(ns|us|µs|μs|ms|s|m|h|d|w|y)`)
+	bytesRE             = regexp.MustCompile(`^([+-]?)(` + magnitudePattern + `)([a-zA-Z]{1,3})$`)
+	// The official semantic versioning regular expression, extended by an
+	// optional leading "v".
+	semVerRE = regexp.MustCompile(`^v?(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)` +
+		`(?:-((?:0|[1-9][0-9]*|[0-9]*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9][0-9]*|[0-9]*[a-zA-Z-][0-9a-zA-Z-]*))*))?` +
+		`(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$`)
+)
+
+// parseNumberValue parses a number, including the infinities. NaN is not a
+// number for sorting purposes, it sorts as an untyped string.
+func parseNumberValue(s string) (typedLabelValue, bool) {
+	if infinityRE.MatchString(s) {
+		if s[0] == '-' {
+			return typedLabelValue{class: classNegativeInf}, true
+		}
+		return typedLabelValue{class: classPositiveInf}, true
+	}
+	if !numberRE.MatchString(s) {
+		return typedLabelValue{}, false
+	}
+	d, ok := parseDecimal(s)
+	if !ok {
+		return typedLabelValue{}, false
+	}
+	return typedLabelValue{class: classNumber, number: d}, true
+}
+
+// durationUnits maps a duration unit to its length in nanoseconds.
+var durationUnits = map[string]int64{
+	"ns": 1,
+	"us": int64(time.Microsecond),
+	"µs": int64(time.Microsecond),
+	"μs": int64(time.Microsecond),
+	"ms": int64(time.Millisecond),
+	"s":  int64(time.Second),
+	"m":  int64(time.Minute),
+	"h":  int64(time.Hour),
+	"d":  24 * int64(time.Hour),
+	"w":  7 * 24 * int64(time.Hour),
+	"y":  365 * 24 * int64(time.Hour),
+}
+
+// parseDurationValue parses a duration like "5m" or "1h30m" into nanoseconds.
+func parseDurationValue(s string) (decimal, bool) {
+	total, ok := newDecimal(0, 0), false
+	for s != "" {
+		m := durationComponentRE.FindStringSubmatch(s)
+		if m == nil {
+			return decimal{}, false
+		}
+		d, valid := parseDecimal(m[1] + m[2])
+		if !valid {
+			return decimal{}, false
+		}
+		total, valid = total.add(d.mulInt64(durationUnits[m[3]]))
+		if !valid {
+			return decimal{}, false
+		}
+		s, ok = s[len(m[0]):], true
+	}
+	return total, ok
+}
+
+// byteUnits maps a byte unit to the number of bytes it stands for.
+var byteUnits = map[string]*big.Int{
+	"b":   big.NewInt(1),
+	"kb":  pow(1000, 1),
+	"mb":  pow(1000, 2),
+	"gb":  pow(1000, 3),
+	"tb":  pow(1000, 4),
+	"pb":  pow(1000, 5),
+	"eb":  pow(1000, 6),
+	"zb":  pow(1000, 7),
+	"yb":  pow(1000, 8),
+	"kib": pow(1024, 1),
+	"mib": pow(1024, 2),
+	"gib": pow(1024, 3),
+	"tib": pow(1024, 4),
+	"pib": pow(1024, 5),
+	"eib": pow(1024, 6),
+	"zib": pow(1024, 7),
+	"yib": pow(1024, 8),
+}
+
+func pow(base, exp int64) *big.Int {
+	return new(big.Int).Exp(big.NewInt(base), big.NewInt(exp), nil)
+}
+
+// parseBytesValue parses a byte size like "512MiB" into bytes.
+func parseBytesValue(s string) (decimal, bool) {
+	m := bytesRE.FindStringSubmatch(s)
+	if m == nil {
+		return decimal{}, false
+	}
+	unit, ok := byteUnits[strings.ToLower(m[3])]
+	if !ok {
+		return decimal{}, false
+	}
+	d, ok := parseDecimal(m[1] + m[2])
+	if !ok {
+		return decimal{}, false
+	}
+	return d.mul(unit), true
+}
+
+// timestampLayouts are the timestamp formats recognized as a timestamp, most
+// specific first. Fractional seconds are accepted by all layouts that have a
+// seconds field.
+var timestampLayouts = []string{
+	time.RFC3339,
+	"2006-01-02T15:04:05",
+	"2006-01-02 15:04:05Z07:00",
+	"2006-01-02 15:04:05",
+	"2006-01-02",
+}
+
+func parseTimestampValue(s string) (time.Time, bool) {
+	for _, layout := range timestampLayouts {
+		if ts, err := time.Parse(layout, s); err == nil {
+			return ts, true
+		}
+	}
+	return time.Time{}, false
+}
+
+// naturalCompare compares two strings in natural sort order. Strings that are
+// indistinguishable in natural order but not identical, like "01" and "1", are
+// ordered lexicographically, so that the result is a total order.
+func naturalCompare(a, b string) int {
+	if a == b {
+		return 0
+	}
+	switch aFirst, bFirst := natsort.Compare(a, b), natsort.Compare(b, a); {
+	case aFirst && !bFirst:
+		return -1
+	case bFirst && !aFirst:
+		return +1
+	default:
+		return strings.Compare(a, b)
+	}
+}
+
+const (
+	// maxDecimalExponent bounds the exponent of a decimal, both to keep the
+	// exponent arithmetic within int64 and to reject absurd inputs.
+	maxDecimalExponent = 1 << 40
+	// maxAlignShift is the largest exponent difference two decimals may
+	// have to be added to each other.
+	maxAlignShift = 1000
+)
+
+// decimal is an exact decimal number, coefficient × 10^exponent. Magnitudes are
+// kept as decimals rather than floats so that comparisons keep their order for
+// arbitrarily large values, without the loss of precision of a float and
+// without expanding the exponent into digits.
+type decimal struct {
+	coefficient *big.Int
+	exponent    int64
+}
+
+func newDecimal(coefficient, exponent int64) decimal {
+	return decimal{coefficient: big.NewInt(coefficient), exponent: exponent}
+}
+
+// parseDecimal parses a decimal number with an optional sign and an optional
+// scientific exponent. It expects an already validated magnitude and only
+// fails on an exponent that is out of range.
+func parseDecimal(s string) (decimal, bool) {
+	digits, exponent := s, int64(0)
+	if e := strings.IndexAny(s, "eE"); e >= 0 {
+		var err error
+		if exponent, err = strconv.ParseInt(strings.TrimPrefix(s[e+1:], "+"), 10, 64); err != nil {
+			return decimal{}, false
+		}
+		digits = s[:e]
+	}
+	if p := strings.IndexByte(digits, '.'); p >= 0 {
+		exponent -= int64(len(digits) - p - 1)
+		digits = digits[:p] + digits[p+1:]
+	}
+	if exponent > maxDecimalExponent || exponent < -maxDecimalExponent {
+		return decimal{}, false
+	}
+
+	coefficient, ok := new(big.Int).SetString(strings.TrimPrefix(digits, "+"), 10)
+	if !ok {
+		return decimal{}, false
+	}
+	return decimal{coefficient: coefficient, exponent: exponent}, true
+}
+
+func (d decimal) mulInt64(factor int64) decimal {
+	return d.mul(big.NewInt(factor))
+}
+
+func (d decimal) mul(factor *big.Int) decimal {
+	return decimal{coefficient: new(big.Int).Mul(d.coefficient, factor), exponent: d.exponent}
+}
+
+// add returns the sum of two decimals. It fails if lining up the exponents
+// would require an unreasonable number of digits.
+func (d decimal) add(o decimal) (decimal, bool) {
+	switch {
+	case d.coefficient.Sign() == 0:
+		return o, true
+	case o.coefficient.Sign() == 0:
+		return d, true
+	}
+	if d.exponent < o.exponent {
+		d, o = o, d
+	}
+	shift := d.exponent - o.exponent
+	if shift > maxAlignShift {
+		return decimal{}, false
+	}
+	coefficient := new(big.Int).Mul(d.coefficient, pow(10, shift))
+	return decimal{coefficient: coefficient.Add(coefficient, o.coefficient), exponent: o.exponent}, true
+}
+
+func (d decimal) compare(o decimal) int {
+	sign, oSign := d.coefficient.Sign(), o.coefficient.Sign()
+	if sign != oSign {
+		return cmp.Compare(sign, oSign)
+	}
+	if sign == 0 {
+		return 0
+	}
+	if sign < 0 {
+		return -d.compareMagnitude(o)
+	}
+	return d.compareMagnitude(o)
+}
+
+// compareMagnitude compares the absolute values of two non-zero decimals.
+func (d decimal) compareMagnitude(o decimal) int {
+	a, aExp := d.digits()
+	b, bExp := o.digits()
+
+	// With the trailing zeros stripped, the value is 0.<digits> × 10^scale,
+	// so a larger scale means a larger magnitude.
+	if c := cmp.Compare(int64(len(a))+aExp, int64(len(b))+bExp); c != 0 {
+		return c
+	}
+	// Same scale: the digits decide, and whichever has digits left over
+	// after the common prefix is the larger one.
+	n := min(len(a), len(b))
+	if c := strings.Compare(a[:n], b[:n]); c != 0 {
+		return c
+	}
+	return cmp.Compare(len(a), len(b))
+}
+
+// digits returns the decimal digits of the coefficient without its sign and
+// without trailing zeros, together with the matching exponent.
+func (d decimal) digits() (string, int64) {
+	digits := strings.TrimPrefix(d.coefficient.String(), "-")
+	trimmed := strings.TrimRight(digits, "0")
+	return trimmed, d.exponent + int64(len(digits)-len(trimmed))
+}
+
+// semVersion is a semantic version. The version core is kept as digits so that
+// arbitrarily large version numbers keep their order. Build metadata is not
+// part of the precedence and therefore not kept.
+type semVersion struct {
+	core       [3]string
+	preRelease []string
+}
+
+// parseSemVersion parses a semantic version with an optional leading "v".
+// Anything that is not a valid semantic version is not a version at all.
+func parseSemVersion(s string) (semVersion, bool) {
+	m := semVerRE.FindStringSubmatch(s)
+	if m == nil {
+		return semVersion{}, false
+	}
+	v := semVersion{core: [3]string{m[1], m[2], m[3]}}
+	if m[4] != "" {
+		v.preRelease = strings.Split(m[4], ".")
+	}
+	return v, true
+}
+
+func (v semVersion) compare(o semVersion) int {
+	for i := range v.core {
+		if c := compareNumericID(v.core[i], o.core[i]); c != 0 {
+			return c
+		}
+	}
+
+	// A version with a pre-release comes before the released version.
+	switch {
+	case len(v.preRelease) == 0 && len(o.preRelease) == 0:
+		return 0
+	case len(v.preRelease) == 0:
+		return +1
+	case len(o.preRelease) == 0:
+		return -1
+	}
+
+	for i, id := range v.preRelease {
+		if i >= len(o.preRelease) {
+			break
+		}
+		oID := o.preRelease[i]
+		numeric, oNumeric := isNumericID(id), isNumericID(oID)
+		switch {
+		case numeric && oNumeric:
+			if c := compareNumericID(id, oID); c != 0 {
+				return c
+			}
+		case numeric != oNumeric:
+			// Numeric identifiers always have lower precedence.
+			if numeric {
+				return -1
+			}
+			return +1
+		default:
+			if c := strings.Compare(id, oID); c != 0 {
+				return c
+			}
+		}
+	}
+	// A larger set of pre-release fields has a higher precedence.
+	return cmp.Compare(len(v.preRelease), len(o.preRelease))
+}
+
+// compareNumericID compares two identifiers of digits without leading zeros.
+func compareNumericID(a, b string) int {
+	if c := cmp.Compare(len(a), len(b)); c != 0 {
+		return c
+	}
+	return strings.Compare(a, b)
+}
+
+func isNumericID(id string) bool {
+	return strings.IndexFunc(id, func(r rune) bool { return r < '0' || r > '9' }) < 0
+}
+
+// labelValueComparer compares label values with typed comparison, caching the
+// parsed values because sorting compares the same value many times.
+type labelValueComparer struct {
+	parsed map[string]typedLabelValue
+}
+
+func newLabelValueComparer() *labelValueComparer {
+	return &labelValueComparer{parsed: map[string]typedLabelValue{}}
+}
+
+func (c *labelValueComparer) compare(a, b string) int {
+	if a == b {
+		return 0
+	}
+	return compareTypedLabelValues(c.parse(a), c.parse(b), a, b)
+}
+
+func (c *labelValueComparer) parse(s string) typedLabelValue {
+	v, ok := c.parsed[s]
+	if !ok {
+		v = parseLabelValue(s)
+		c.parsed[s] = v
+	}
+	return v
+}
