+func TestCompareLabelValues(t *testing.T) {
+	for i, a := range labelValuesInOrder {
+		require.Zero(t, compareLabelValues(a, a), "%q should be equal to itself", a)
+
+		for _, b := range labelValuesInOrder[i+1:] {
+			require.Negative(t, compareLabelValues(a, b), "%q should sort before %q", a, b)
+			require.Positive(t, compareLabelValues(b, a), "%q should sort after %q", b, a)
+		}
+	}
+}
+
+func TestCompareLabelValuesSorts(t *testing.T) {
+	shuffled := slices.Clone(labelValuesInOrder)
+	rnd := rand.New(rand.NewSource(42))
+	for range 10 {
+		rnd.Shuffle(len(shuffled), func(i, j int) { shuffled[i], shuffled[j] = shuffled[j], shuffled[i] })
+
+		sorted := slices.Clone(shuffled)
+		slices.SortFunc(sorted, compareLabelValues)
+		require.Equal(t, labelValuesInOrder, sorted)
+	}
+}
+
+func TestLabelValueComparerMatchesCompareLabelValues(t *testing.T) {
+	comparer := newLabelValueComparer()
+	for _, a := range labelValuesInOrder {
+		for _, b := range labelValuesInOrder {
+			require.Equal(t, compareLabelValues(a, b), comparer.compare(a, b), "comparing %q and %q", a, b)
+		}
+	}
+}
