+func TestCompareLabelValuesTieBreak(t *testing.T) {
+	// Values that are equal after parsing are ordered by the natural order
+	// of the original strings.
+	for _, tc := range []struct{ a, b string }{
+		{a: "0", b: "0.0"},
+		{a: "1", b: "1e0"},
+		{a: "+Inf", b: "Inf"},
+		{a: "-Inf", b: "-inf"},
+		{a: "1m", b: "60s"},
+		{a: "1kB", b: "1000B"},
+		{a: "1.0.0", b: "1.0.0+build"},
+		{a: "1.0.0+build", b: "v1.0.0"},
+		{a: "2024-01-02T00:00:00Z", b: "2024-01-02T01:00:00+01:00"},
+		{a: "01", b: "1"},
+	} {
+		require.Negative(t, compareLabelValues(tc.a, tc.b), "%q should sort before %q", tc.a, tc.b)
+		require.Positive(t, compareLabelValues(tc.b, tc.a), "%q should sort after %q", tc.b, tc.a)
+	}
+}
+
+func TestNaturalCompare(t *testing.T) {
+	for _, tc := range []struct {
+		a, b string
+		want int
+	}{
+		{a: "", b: "", want: 0},
+		{a: "abc", b: "abc", want: 0},
+		{a: "", b: "a", want: -1},
+		{a: "a2", b: "a10", want: -1},
+		{a: "a10", b: "a2", want: +1},
+		{a: "4m5", b: "4m600", want: -1},
+		{a: "4m600", b: "4m1000", want: -1},
+		// Indistinguishable in natural order, ordered lexicographically.
+		{a: "01", b: "1", want: -1},
+		{a: "1", b: "01", want: +1},
+	} {
+		require.Equal(t, tc.want, naturalCompare(tc.a, tc.b), "comparing %q and %q", tc.a, tc.b)
+	}
+}
